// Turn usage numbers into a short report for leaders (send it on with an Email, Slack or Teams node).
const r = $input.first().json;
const hours = (r.minutesSaved / 60).toFixed(1);
const channels = Object.entries(r.byChannel).map(([k, v]) => `${k}: ${v}`).join(', ') || 'none';
const lines = [
  'AI knowledge base: weekly impact',
  `Lookups: ${r.totalLookups} by ${r.activeUsers} ${r.activeUsers === 1 ? 'person' : 'people'} (${channels})`,
  `Answered: ${Math.round(r.answeredRate * 100)}% of searches`,
  `Estimated time saved: ${hours} hours`,
  r.unanswered.length ? `Questions to add to the knowledge base: ${r.unanswered.join('; ')}` : 'No unanswered questions this week'
];
return [{ json: { report: lines.join('\n'), hoursSaved: Number(hours), lookups: r.totalLookups, gaps: r.unanswered } }];
